import json,re,html
s={x['source_id']:x for x in json.load(open('source.json'))}
a=json.load(open('answer.json'))
def canonical(x):return re.sub(r'\\s+',' ',html.unescape(re.sub(r'<["'^>]+>'"','',x or ''))).strip()
for x in a:
 for e in x['substantive_impact']['effects']:
  for field,body in [('source_quote',s[x['source_id']]['source_xml']),('proposed_quote',x['proposed_xml'])]:
   if e[field] not in canonical(body):print(x['number'],field,repr(e[field]))
